#include "../../../include/bst/header.h"

// ========== Created - Assertion Operations ==========

// Asserts that a tree contains a specific key by performing a search
void helper_assert_tree_contains(struct node *root, int key) {
    struct node *current = root;
    while (current != NULL) {
        if (key == current->key) {
            return;
        } else if (key < current->key) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
    assert(0 && "Key not found in tree");
}

// Asserts that a tree does not contain a specific key by performing a search
void helper_assert_tree_not_contains(struct node *root, int key) {
    struct node *current = root;
    while (current != NULL) {
        if (key == current->key) {
            assert(0 && "Key found in tree");
        } else if (key < current->key) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
}

static void inorder_traversal(struct node *root, char *buffer, int *index) {
    if (root == NULL) return;
    inorder_traversal(root->left, buffer, index);
    *index += snprintf(buffer + *index, 1024 - *index, "%d ", root->key);
    inorder_traversal(root->right, buffer, index);
}

// Asserts that the inorder traversal of a tree matches an expected string
void helper_assert_tree_inorder(struct node *root, const char *expected) {
    char buffer[1024];
    int index = 0;
    buffer[0] = '\0';

    inorder_traversal(root, buffer, &index);

    TEST_ASSERT_EQUAL_STRING(expected, buffer);
}

// ========== Created - Utility Operations ==========

// Builds a binary search tree from an array of integer values
struct node* helper_build_tree(int *values, int size) {
    struct node *root = NULL;
    for (int i = 0; i < size; i++) {
        root = insert(root, values[i]);
    }
    return root;
}

// Frees all nodes in a binary search tree using post-order traversal
void helper_free_tree(struct node *root) {
    if (root != NULL) {
        helper_free_tree(root->left);
        helper_free_tree(root->right);
        free(root);
    }
}

